func TestCachedEmbedderEmbedBatch_PartialHit(t *testing.T) {
	inner := newCountingEmbedder()
	cached := NewCachedEmbedder(inner, 64)

	ctx := context.Background()

	_, _ = cached.Embed(ctx, "alpha")

	texts := []string{"alpha", "beta", "gamma", "alpha"}

	result, err := cached.EmbedBatch(ctx, texts)
	if err != nil {
		t.Fatalf("EmbedBatch: %v", err)
	}
	if inner.totalCalls() != 1 {
		t.Errorf("after partial-hit EmbedBatch: inner calls = %d, want 1 (only beta,gamma fetched)", inner.totalCalls())
	}
	if len(result) != len(texts) {
		t.Fatalf("result length = %d, want %d", len(result), len(texts))
	}

	for i, text := range texts {
		if result[i] == nil {
			t.Errorf("result[%d] is nil, want non-nil", i)
			continue
		}
		expected := []float64{float64(len(text)), 0, 0}
		if len(result[i]) != len(expected) {
			t.Errorf("result[%d] len = %d, want %d", i, len(result[i]), len(expected))
			continue
		}
		for j, v := range expected {
			if result[i][j] != v {
				t.Errorf("result[%d][%d] = %v, want %v", i, j, result[i][j], v)
			}
		}
	}

	if inner.callCount("alpha") != 0 {
		t.Errorf("alpha inner calls = %d, want 0 (was cached before EmbedBatch)", inner.callCount("alpha"))
	}
	if inner.callCount("beta") != 1 {
		t.Errorf("beta inner calls = %d, want 1", inner.callCount("beta"))
	}
	if inner.callCount("gamma") != 1 {
		t.Errorf("gamma inner calls = %d, want 1", inner.callCount("gamma"))
	}
}

